// Every command of the app, as `generate_handler!` registers them (src/lib.rs). Declaring them
// turns the app's own commands over to the capabilities (capabilities/*.json, NATIVE-011): a
// window may call only the commands its capability allows (`allow-<command>`), no longer all of
// them. tauri-build writes their permissions to permissions/autogenerated (ignored by Git).
// src/acl.rs checks that this list, the handler and the capabilities agree.
const COMMANDS: &[&str] = &[
    "get_settings",
    "settings_recovery",
    "glass_frame",
    "save_settings",
    "reset_settings",
    "suggest_shortcut",
    "capture_text",
    "frontend_ready",
    "translate",
    "cancel_translation",
    "copy_result",
    "replace_result",
    "result_pill",
    "move_overlay",
    "highlight_changes",
    "undo_result",
    "dismiss_overlay",
    "complete_overlay_dismiss",
    "open_settings",
    "shortcut_status",
    "focus_overlay",
    "choose_action",
    "shortcut_conflict",
    "override_cursor",
    "demo_menu_capture",
    "resize_overlay",
    "overlay_dimming",
    "drag_settings",
    "quit_app",
    "start_drag",
    "probe_connection",
    "cancel_probe",
    "try_model",
    "get_diagnostics",
    "clear_diagnostics",
    "open_setup",
    "finish_setup",
    "complete_setup",
    "open_demo",
    "close_demo",
    "get_history",
    "delete_history",
    "system_theme",
    "system_motion",
    "update_status",
    "check_update",
    "install_update",
];

fn main() {
    let attributes = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS));
    if let Err(error) = tauri_build::try_build(attributes) {
        // The whole cause chain (an unknown permission in a capability, for instance).
        panic!("{error:#}");
    }
}
